#include "RecreationSearch.h"
#include <iostream>
#include <stdexcept>
int main(){try{std::atomic<bool> cancel{false};std::cout<<"[\n";for(int family:{0,3}){nova::Params patch;patch.engine=family;patch.root=69;patch.fm=.28f;patch.mix=.63f;patch.noise=.013f;patch.attack=.019f;patch.decay=.22f;patch.sustain=.6f;patch.cutoff=6100;patch.reverb=.12f;patch.delay=patch.chorus=0;patch.unison=false;patch.detune=0;nova::Engine renderer;renderer.prepare(16000);renderer.configure(patch);nova::Sound source;source.sampleRate=16000;source.left.resize(22400);source.right=source.left;renderer.noteOn(1,69,.8f);renderer.render(source.left.data(),source.right.data(),11200);renderer.reset();renderer.noteOn(1,72,.6f);renderer.render(source.left.data()+11200,source.right.data()+11200,11200);auto baseline=nova::searchRecreation(source,0,1200,true,true,0,cancel);auto exhaustive=nova::searchRecreation(source,0,3600,true,true,0,cancel);if(!baseline.fit.valid||!exhaustive.fit.valid||exhaustive.fit.bestError>baseline.fit.bestError+1e-8||exhaustive.fit.parameters.fineTune!=0||exhaustive.fit.trials<baseline.fit.trials)throw std::runtime_error("Exhaustive search regressed baseline or pitch");std::cout<<"{\"synthetic_engine\":"<<family<<",\"baseline_loss\":"<<baseline.fit.bestError<<",\"exhaustive_loss\":"<<exhaustive.fit.bestError<<",\"baseline_trials\":"<<baseline.fit.trials<<",\"exhaustive_trials\":"<<exhaustive.fit.trials<<"}"<<(family==0?",\n":"\n");}std::cout<<"]\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
